CREATE TABLE IF NOT EXISTS StudentProfiles (
Id INTEGER PRIMARY KEY AUTOINCREMENT, Name TEXT NOT NULL, Address TEXT NOT NULL, CollegeName TEXT NOT NULL, FieldOfStudy TEXT NOT NULL, JobRole TEXT NOT NULL, ImagePath TEXT NULL, DegreeCertificatePath TEXT NULL, MarksheetPath TEXT NULL, CertificationsPath TEXT NULL, VideoPath TEXT NULL, Email TEXT NULL, CreatedOn TEXT NOT NULL);

DELETE FROM StudentProfiles;
